function(variables) {
	var g = variables.company && variables.company.IsVerified
	? new ReadOnlyDetailView(variables.element) 
	: new WritableDetailView(variables.element, {data: variables.company} );

	g.title = "#=(IsVerified) ? '<span class=\"k-icon k-i-check\" ></span>': '<span class=\"k-icon k-i-close\" ></span>'# #:Name#";
	// optional, but we want a subset of fields here so lets be explicit.
	g.fields =
		model.propertiesFor("B2B/Company", ["Name", "ContactPhoneNumber", "ContactEmailAddress", "WebsiteUrl"])
		.concat(model.propertiesFor("B2B/Address", ["PoBox", "Line1", "Line2", "TownOrCity", "StateOrProvince", "ZipOrPostalCode", "CountryId"]).map(p => 
		{
			p.field = "Address." + p.field;
			return p;
		}));
	g.toolbar = "<button onClick='javascript: history.go(-1)'><span class='k-icon k-i-arrow-parent'></span> [resource_shortdisplayname[Back]]</button>";
    variables.CompanyDetails = g;
    return g;
}
